"""Algorithm 1: divisor-recursive construction of the cyclotomic polynomial Phi_n."""

from __future__ import annotations

from typing import Dict, List, Tuple

Poly = List[int]  # dense coefficients, index = exponent

_CACHE: Dict[int, Poly] = {}


def divisors(n: int) -> List[int]:
    """All positive divisors of n in ascending order, in O(sqrt n)."""
    small, large = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            small.append(i)
            if i != n // i:
                large.append(n // i)
        i += 1
    return small + large[::-1]


def poly_divmod_monic(num: Poly, den: Poly) -> Tuple[Poly, Poly]:
    """Exact long division of integer polynomials by a monic divisor."""
    assert den[-1] == 1
    rem = list(num)
    d = len(den) - 1
    if len(rem) - 1 < d:
        return [0], rem
    quo = [0] * (len(rem) - d)
    for i in range(len(rem) - 1, d - 1, -1):
        c = rem[i]
        quo[i - d] = c
        if c:
            for j in range(d + 1):
                rem[i - d + j] -= c * den[j]
    return quo, rem[:d] if d > 0 else [0]


def cyclotomic(n: int) -> Poly:
    """
    Phi_n, computed from the divisor product identity  prod_{d | n} Phi_d = X^n - 1.

    Start with X^n - 1 and divide out Phi_d for every proper divisor d.  Each Phi_d is
    monic, so all divisions are exact over the integers and no denominators appear.
    """
    if n in _CACHE:
        return _CACHE[n]
    cur: Poly = [-1] + [0] * (n - 1) + [1]
    for d in divisors(n):
        if d < n:
            cur, rem = poly_divmod_monic(cur, cyclotomic(d))
            assert all(c == 0 for c in rem), "non-exact division: identity violated"
    while len(cur) > 1 and cur[-1] == 0:
        cur.pop()
    _CACHE[n] = cur
    return cur


def height(n: int) -> int:
    """H(n) = max |coefficient| of Phi_n."""
    return max(abs(c) for c in cyclotomic(n))


if __name__ == "__main__":
    for n in (15, 105, 231, 385):
        print(f"deg Phi_{n} = {len(cyclotomic(n)) - 1},  H({n}) = {height(n)}")

"""Algorithm 2: height computation accelerated by reduction to the odd radical."""

from __future__ import annotations

from typing import Dict, List, Tuple

Poly = List[int]
_CACHE: Dict[int, Poly] = {}


def prime_factorization(n: int) -> List[Tuple[int, int]]:
    """Trial-division factorization of n as a list of (prime, exponent), O(sqrt n)."""
    out: List[Tuple[int, int]] = []
    m, d = n, 2
    while d * d <= m:
        if m % d == 0:
            e = 0
            while m % d == 0:
                m //= d
                e += 1
            out.append((d, e))
        d += 1
    if m > 1:
        out.append((m, 1))
    return out


def odd_radical(n: int) -> int:
    """rad_odd(n): the product of the odd primes dividing n; 1 if n is a power of two."""
    r = 1
    for p, _ in prime_factorization(n):
        if p != 2:
            r *= p
    return r


def euler_phi(n: int) -> int:
    """Euler's totient from the factorization; deg Phi_n = phi(n)."""
    r = 1
    for p, e in prime_factorization(n):
        r *= (p - 1) * p ** (e - 1)
    return r


def divisors(n: int) -> List[int]:
    small, large = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            small.append(i)
            if i != n // i:
                large.append(n // i)
        i += 1
    return small + large[::-1]


def cyclotomic(n: int) -> Poly:
    if n in _CACHE:
        return _CACHE[n]
    cur: Poly = [-1] + [0] * (n - 1) + [1]
    for d in divisors(n):
        if d < n:
            den = cyclotomic(d)
            deg = len(den) - 1
            for i in range(len(cur) - 1, deg - 1, -1):
                c = cur[i]
                if c:
                    for j in range(deg + 1):
                        cur[i - deg + j] -= c * den[j]
                    cur[i] = c
            quo = cur[deg:]
            cur = quo
    while len(cur) > 1 and cur[-1] == 0:
        cur.pop()
    _CACHE[n] = cur
    return cur


def height_reduced(n: int) -> Tuple[int, int, int, int]:
    """
    Compute H(n) using the reduction H(n) = H(rad_odd(n)).

    Returns (height, odd_radical, deg Phi_n, deg Phi_{rad_odd(n)}); the last two numbers
    quantify the saving, which is unbounded (deg Phi_n grows with the powers of 2 and the
    repeated prime factors, while deg Phi_{rad_odd(n)} does not).
    """
    r = odd_radical(n)
    if r <= 1:
        return 1, r, euler_phi(n), 1
    h = max(abs(c) for c in cyclotomic(r))
    return h, r, euler_phi(n), euler_phi(r)


if __name__ == "__main__":
    for n in (105, 2520, 352800, 231, 6468, 385, 3850, 2 ** 10 * 3 ** 4 * 5 ** 3 * 7 ** 2):
        h, r, dn, dr = height_reduced(n)
        print(f"n = {n:<12} rad_odd = {r:<5} H = {h}   (deg Phi_n = {dn}, deg Phi_rad = {dr})")
